// Service worker: keeps a copy of the app on the phone so it opens with no connection
// (at the register, in a mall basement). The data itself lives in IndexedDB.
// The asset list and version below are generated by `npm run stamp`; do not edit by hand.

// <assets>
const VERSION = 'gw-9b5b4cf73cb9';
const OCR_VERSION = 'gw-ocr-3ebbe61b4ea3';
const ASSETS = [
  'backend/Code.gs',
  'css/app.css',
  'fonts/heebo-hebrew.woff2',
  'fonts/heebo-latin.woff2',
  'icons/apple-touch-icon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
  'icons/icon.svg',
  'index.html',
  'js/lib/backup.js',
  'js/lib/catalog.js',
  'js/lib/code128.js',
  'js/lib/crypto.js',
  'js/lib/dates.js',
  'js/lib/db.js',
  'js/lib/events.js',
  'js/lib/ids.js',
  'js/lib/image.js',
  'js/lib/model.js',
  'js/lib/money.js',
  'js/lib/ocr-text.js',
  'js/lib/ocr.js',
  'js/lib/parse-text.js',
  'js/lib/platform.js',
  'js/lib/qr.js',
  'js/lib/reminders.js',
  'js/lib/store.js',
  'js/lib/sync.js',
  'js/main.js',
  'js/theme-boot.js',
  'js/ui/app.js',
  'js/ui/archive.js',
  'js/ui/card-detail.js',
  'js/ui/card-form.js',
  'js/ui/cashier.js',
  'js/ui/components.js',
  'js/ui/core.js',
  'js/ui/history.js',
  'js/ui/icons.js',
  'js/ui/members.js',
  'js/ui/onboarding.js',
  'js/ui/paste.js',
  'js/ui/photos.js',
  'js/ui/scanner.js',
  'js/ui/settings.js',
  'js/ui/sync-pill.js',
  'js/ui/sync-setup.js',
  'js/ui/tx-sheet.js',
  'js/ui/wallet.js',
  'js/vendor/preact-htm.js',
  'js/vendor/qrcode.js',
  'js/version.js',
  'manifest.webmanifest',
];
// </assets>

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(VERSION).then((cache) => cache.addAll(['./', ...ASSETS])));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('gw-') && k !== VERSION && k !== OCR_VERSION).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

// Text recognition files are fetched the first time someone scans and kept from then on.
const isOnDemand = (path) => /\/(?:ocr|js\/vendor\/tesseract)\//.test(path);

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    // Any page load (including share-target URLs with a query string) gets the app shell.
    event.respondWith((async () => {
      const cached = await caches.match('index.html', { ignoreSearch: true });
      if (cached) return cached;
      try {
        return await fetch(req);
      } catch {
        return (await caches.match('./')) || Response.error();
      }
    })());
    return;
  }

  if (isOnDemand(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(OCR_VERSION);
      const cached = await cache.match(req, { ignoreSearch: true });
      if (cached) return cached;
      const res = await fetch(req);
      if (res.ok) await cache.put(req, res.clone());
      return res;
    })());
    return;
  }

  event.respondWith((async () => {
    const cached = await caches.match(req, { ignoreSearch: true });
    return cached || fetch(req);
  })());
});
